const MATCH_ROUNDS = [{"title": "Must Know Match", "type": "phrases", "pairs": [{"english": "Hello.", "greek": "Γεια σας."}, {"english": "Good morning.", "greek": "Καλημέρα σας."}, {"english": "Good evening.", "greek": "Καλησπέρα σας."}, {"english": "Good night.", "greek": "Καληνύχτα σας."}, {"english": "Thank you.", "greek": "Ευχαριστώ πολύ."}]}, {"title": "Café & Drinks Match", "type": "phrases", "pairs": [{"english": "One coffee, please.", "greek": "Έναν καφέ, παρακαλώ."}, {"english": "I would like a coffee, please.", "greek": "Θα ήθελα έναν καφέ, παρακαλώ."}, {"english": "I would like water, please.", "greek": "Θα ήθελα νερό, παρακαλώ."}, {"english": "Still water, please.", "greek": "Νερό χωρίς ανθρακικό, παρακαλώ."}, {"english": "Sparkling water, please.", "greek": "Ανθρακούχο νερό, παρακαλώ."}]}, {"title": "Buildable Questions Match", "type": "phrases", "pairs": [{"english": "Do you have this?", "greek": "Το έχετε αυτό;"}, {"english": "Do you have water?", "greek": "Έχετε νερό;"}, {"english": "Do you have a bathroom?", "greek": "Έχετε τουαλέτα;"}, {"english": "Can I have this?", "greek": "Μπορώ να πάρω αυτό;"}, {"english": "Can I get one coffee?", "greek": "Μπορώ να πάρω έναν καφέ;"}]}, {"title": "What & Where Questions Match", "type": "phrases", "pairs": [{"english": "What is this?", "greek": "Τι είναι αυτό;"}, {"english": "What is that?", "greek": "Τι είναι εκείνο;"}, {"english": "What is this called?", "greek": "Πώς λέγεται αυτό;"}, {"english": "What does this word mean?", "greek": "Τι σημαίνει αυτή η λέξη;"}, {"english": "What should I say?", "greek": "Τι να πω;"}]}, {"title": "At Home & Family Match", "type": "phrases", "pairs": [{"english": "Thank you for the food.", "greek": "Σας ευχαριστώ για το φαγητό."}, {"english": "Can I help?", "greek": "Μπορώ να βοηθήσω;"}, {"english": "Do you need help?", "greek": "Χρειάζεστε βοήθεια;"}, {"english": "I will help.", "greek": "Θα βοηθήσω."}, {"english": "Where should I put this?", "greek": "Πού να το βάλω αυτό;"}]}, {"title": "Shopping & Grocery Match", "type": "phrases", "pairs": [{"english": "How much is this?", "greek": "Πόσο κάνει αυτό;"}, {"english": "I will take this.", "greek": "Θα πάρω αυτό."}, {"english": "I am just looking.", "greek": "Απλώς κοιτάω."}, {"english": "Do you have a bigger size?", "greek": "Έχετε μεγαλύτερο μέγεθος;"}, {"english": "Do you have a smaller size?", "greek": "Έχετε μικρότερο μέγεθος;"}]}, {"title": "Conversation Repair Match", "type": "phrases", "pairs": [{"english": "I don't understand.", "greek": "Δεν καταλαβαίνω."}, {"english": "Can you repeat that?", "greek": "Μπορείτε να το επαναλάβετε;"}, {"english": "Can you speak more slowly?", "greek": "Μπορείτε να μιλάτε πιο αργά;"}, {"english": "More slowly, please.", "greek": "Πιο αργά, παρακαλώ."}, {"english": "Can you say it in English?", "greek": "Μπορείτε να το πείτε στα αγγλικά;"}]}, {"title": "Colors Vocab Match", "type": "vocabulary", "pairs": [{"english": "black color", "greek": "μαύρο"}, {"english": "white color", "greek": "λευκό"}, {"english": "blue color", "greek": "μπλε"}, {"english": "red color", "greek": "κόκκινο"}, {"english": "green color", "greek": "πράσινο"}]}, {"title": "Place & Position Vocab Match", "type": "vocabulary", "pairs": [{"english": "in/inside", "greek": "μέσα"}, {"english": "outside", "greek": "έξω"}, {"english": "on/top of", "greek": "πάνω σε"}, {"english": "under/below", "greek": "κάτω από"}, {"english": "up", "greek": "πάνω"}]}, {"title": "Practical Time Vocab Match", "type": "vocabulary", "pairs": [{"english": "this morning", "greek": "σήμερα το πρωί"}, {"english": "this afternoon", "greek": "σήμερα το απόγευμα"}, {"english": "tonight", "greek": "απόψε"}, {"english": "next week", "greek": "την επόμενη εβδομάδα"}, {"english": "last week", "greek": "την προηγούμενη εβδομάδα"}]}, {"title": "Food Basics Vocab Match", "type": "vocabulary", "pairs": [{"english": "food", "greek": "φαγητό"}, {"english": "breakfast", "greek": "πρωινό"}, {"english": "lunch", "greek": "μεσημεριανό"}, {"english": "dinner", "greek": "βραδινό"}, {"english": "bread", "greek": "ψωμί"}]}, {"title": "Home & Objects Vocab Match", "type": "vocabulary", "pairs": [{"english": "house", "greek": "σπίτι"}, {"english": "room", "greek": "δωμάτιο"}, {"english": "bedroom", "greek": "υπνοδωμάτιο"}, {"english": "bathroom", "greek": "μπάνιο"}, {"english": "kitchen", "greek": "κουζίνα"}]}, {"title": "Wi-Fi & Phone Vocab Match", "type": "vocabulary", "pairs": [{"english": "Wi-Fi", "greek": "Wi-Fi"}, {"english": "signal", "greek": "σήμα"}, {"english": "phone charger", "greek": "φορτιστής κινητού"}, {"english": "power bank", "greek": "power bank"}, {"english": "battery is low", "greek": "η μπαταρία είναι χαμηλή"}]}];
const $=id=>document.getElementById(id);
let state=JSON.parse(localStorage.getItem('greek_v104_state')||'{"marks":{},"personal":[],"xp":0,"done":0,"correct":0,"lastDay":"","streak":0}');
function save(){localStorage.setItem('greek_v104_state',JSON.stringify(state));updateStats();}
function today(){return new Date().toISOString().slice(0,10)}
function bumpXP(n=1,correct=false){if(state.lastDay!==today()){state.streak=(state.lastDay?state.streak+1:1);state.lastDay=today()}state.xp+=n;state.done++; if(correct)state.correct++; save();}
function showView(v){document.querySelectorAll('.view').forEach(x=>x.classList.remove('active'));$(v).classList.add('active');document.querySelectorAll('.navBtn').forEach(b=>b.classList.toggle('active',b.dataset.view===v)); if(v==='speak')renderSpeak(); if(v==='vocab')renderVocab(); if(v==='play')renderGameMenu(); if(v==='match')renderMatchMenu(); if(v==='builder')renderPersonal(); if(v==='review')renderReview('review'); window.scrollTo({top:0,behavior:'smooth'});}
function setup(){phraseCount.textContent=DATA.phrases.length+' phrases';vocabCount.textContent=DATA.vocab.length+' words';phraseCountHome.textContent=DATA.phrases.length+' phrases';vocabCountHome.textContent=DATA.vocab.length+' words';matchCountHome.textContent=MATCH_ROUNDS.length+' starter rounds';matchRoundCount.textContent=MATCH_ROUNDS.length+' rounds';speakCategory.innerHTML=['All categories',...new Set(DATA.phrases.map(x=>x.category))].map(c=>`<option>${c}</option>`).join('');vocabCategory.innerHTML=['All categories',...new Set(DATA.vocab.map(x=>x.category))].map(c=>`<option>${c}</option>`).join('');updateStats();}
function updateStats(){xpStat.textContent=state.xp;streakStat.textContent=state.streak||0;playDone.textContent=state.done||0;playCorrect.textContent=state.correct||0;playXP.textContent=state.xp||0;let total=DATA.phrases.length+DATA.vocab.length+state.personal.length;let vals=Object.values(state.marks);countReview.textContent=vals.filter(x=>x==='review').length;countMastered.textContent=vals.filter(x=>x==='mastered').length;countUnmarked.textContent=total-vals.length;}
function mark(id,val){if(val==='clear')delete state.marks[id]; else state.marks[id]=val; save(); renderVisible();}
function renderVisible(){if(speak.classList.contains('active'))renderSpeak(); if(vocab.classList.contains('active'))renderVocab(); if(review.classList.contains('active'))renderReview(currentReview||'review');}
function badge(id){let m=state.marks[id];return m?`<span class="countBadge">${m==='review'?'Needs Review':'Mastered'}</span>`:''}
function itemClass(id){let m=state.marks[id];return m==='review'?' status-review':m==='mastered'?' status-mastered':''}
function activeMark(id,val){return state.marks[id]===val?' isActive':''}
function phraseHTML(p,i){let id='p_'+i;return `<div class="item${itemClass(id)}"><div class="label">${p.category}</div><div class="itemFront">${p.english} ${badge(id)}</div><div class="toneGrid"><div class="toneBox"><div class="label">Casual</div><div class="greek">${p.casual}</div><div class="pron">${p.pronCasual||''}</div></div><div class="toneBox"><div class="label">Formal / polite</div><div class="greek">${p.formal}</div><div class="pron">${p.pronFormal||''}</div></div></div>${p.note?`<div class="notice">${p.note}</div>`:''}<div class="actions"><button class="btn review${activeMark(id,'review')}" onclick="mark('${id}','review')">Needs Review</button><button class="btn master${activeMark(id,'mastered')}" onclick="mark('${id}','mastered')">Mastered</button><button class="btn" onclick="mark('${id}','clear')">Unmarked</button></div></div>`}
function vocabHTML(v,i){let id='v_'+i;return `<div class="item${itemClass(id)}"><div class="label">${v.category}</div><div class="itemFront">${v.english} ${badge(id)}</div><div class="greek">${v.greek}</div><div class="pron">${v.pron||''}</div><div class="actions"><button class="btn review${activeMark(id,'review')}" onclick="mark('${id}','review')">Needs Review</button><button class="btn master${activeMark(id,'mastered')}" onclick="mark('${id}','mastered')">Mastered</button><button class="btn" onclick="mark('${id}','clear')">Unmarked</button></div></div>`}
function renderSpeak(){let q=(speakSearch.value||'').toLowerCase(), c=speakCategory.value;let arr=DATA.phrases.filter(x=>(c==='All categories'||x.category===c)&&JSON.stringify(x).toLowerCase().includes(q));speakList.innerHTML=arr.map(x=>phraseHTML(x,DATA.phrases.indexOf(x))).join('')||'<div class="notice">No phrases found.</div>'}
function renderVocab(){let q=(vocabSearch.value||'').toLowerCase(), c=vocabCategory.value;let arr=DATA.vocab.filter(x=>(c==='All categories'||x.category===c)&&JSON.stringify(x).toLowerCase().includes(q));vocabList.innerHTML=arr.map(x=>vocabHTML(x,DATA.vocab.indexOf(x))).join('')||'<div class="notice">No vocabulary found.</div>'}
let currentReview='review';function renderReview(kind){currentReview=kind;let items=[];DATA.phrases.forEach((p,i)=>items.push({kind:'p',i,id:'p_'+i,title:p.english,sub:p.formal,cat:p.category}));DATA.vocab.forEach((v,i)=>items.push({kind:'v',i,id:'v_'+i,title:v.english,sub:v.greek,cat:v.category}));state.personal.forEach((p,i)=>items.push({kind:'personal',i,id:'personal_'+i,title:p.english,sub:p.greek,cat:p.category||'Personal'}));let arr=items.filter(x=>kind==='unmarked'?!state.marks[x.id]:state.marks[x.id]===kind);reviewList.innerHTML=`<div class="notice">Showing ${kind==='review'?'Priority Needs Review':kind==='mastered'?'Priority Mastered':'Unmarked'}: ${arr.length}</div>`+arr.slice(0,250).map(x=>`<div class="item${itemClass(x.id)}"><div class="label">${x.cat}</div><div class="itemFront">${x.title} ${badge(x.id)}</div><div class="greek">${x.sub}</div><div class="actions"><button class="btn review${activeMark(x.id,'review')}" onclick="mark('${x.id}','review')">Needs Review</button><button class="btn master${activeMark(x.id,'mastered')}" onclick="mark('${x.id}','mastered')">Mastered</button><button class="btn" onclick="mark('${x.id}','clear')">Unmarked</button></div></div>`).join('')}
const gameDefs=[['missions','Situation Missions','8 missions / 40 steps'],['sentenceBuilders','Sentence Builder','30 challenges'],['recognition','Greek → English Recognition','40 challenges'],['englishMatching','English → Greek Matching','25 challenges'],['patterns','Pattern Builder','35 challenges'],['dialogues','Dialogue Games','15 mini-dialogues'],['noFreeze','No Freeze Speed Rounds','10 rounds'],['boss','Boss Battles','5 tests']];
function renderGameMenu(){gameMenu.style.display='block';gameMenu.innerHTML=gameDefs.map(([k,t,s])=>`<button class="gameType" onclick="startGame('${k}',0)"><div>${t}<small>${s}</small></div><span>›</span></button>`).join('');gameArea.innerHTML='';updateStats();}
let currentGame=null,currentIndex=0,gameFlat=[];function flatten(kind){if(kind==='missions'){let arr=[];PLAY.missions.forEach(m=>m.steps.forEach((s,i)=>arr.push({...s,mission:m.title,goal:m.goal,step:i+1,total:m.steps.length})));return arr}return PLAY[kind]||[]}
function startGame(kind,idx=0){currentGame=kind;gameFlat=flatten(kind);currentIndex=idx;gameMenu.style.display='none';renderGameQuestion();setTimeout(()=>{play.scrollIntoView({behavior:'smooth',block:'start'});},40);}
function shuffle(a){return [...a].sort(()=>Math.random()-.5)}
function renderGameQuestion(){let g=gameFlat[currentIndex];if(!g){gameArea.innerHTML='<div class="notice">Game complete. Great job.</div>';return}let pct=Math.round((currentIndex/gameFlat.length)*100);let label=currentGame==='missions'?`${g.mission} — Step ${g.step}/${g.total}`:gameDefs.find(x=>x[0]===currentGame)[1];let body=''; if(currentGame==='sentenceBuilders'){body=renderBuilderGame(g)}else if(currentGame==='patterns'){body=renderPatternGame(g)}else{body=renderMCGame(g)}gameArea.innerHTML=`<div class="gameCard"><button type="button" class="btn inlineTopBtn" onclick="renderGameMenu();play.scrollIntoView({behavior:'smooth',block:'start'});">← Back to Play categories</button><div class="label">${label}</div><div class="progressBar"><div class="progressFill" style="width:${pct}%"></div></div>${body}</div>`;attachGameHandlers();}
let currentMCOptions=[],currentMCAnswer='';
function renderMCGame(g){let opts=shuffle(g.choices);currentMCOptions=opts;currentMCAnswer=g.answer;return `<h3>${escapeHTML(g.prompt)}</h3>${g.greek?`<div class="greek">${escapeHTML(g.greek)}</div>`:''}<div class="choiceList">${opts.map((o,i)=>`<button type="button" class="choice js-choice" data-choice-index="${i}">${escapeHTML(o)}</button>`).join('')}</div><div id="gameFeedback"></div>`}
function answerMC(btn,choice,answer){let ok=choice===answer;btn.classList.add(ok?'correct':'wrong');[...btn.parentNode.querySelectorAll('.choice')].forEach(b=>{b.disabled=true;if(currentMCOptions[+b.dataset.choiceIndex]===answer)b.classList.add('correct')});document.getElementById('gameFeedback').innerHTML=`<div class="notice ${ok?'':'warn'}">${ok?'Correct +10 XP':'Review this one. Correct answer: '+escapeHTML(answer)}</div><button type="button" class="btn primary" id="nextGameBtn">Next</button>`;document.getElementById('nextGameBtn').addEventListener('click',()=>nextGame(ok));}
function nextGame(ok){bumpXP(ok?10:2,ok);currentIndex++;renderGameQuestion();}
let buildSelected=[],currentBuilderBlocks=[],currentBuilderAnswer='';function renderBuilderGame(g){let blocks=shuffle(g.blocks);buildSelected=[];currentBuilderBlocks=blocks;currentBuilderAnswer=g.answer;return `<h3>${escapeHTML(g.prompt)}</h3><div class="answerBlocks" id="answerBlocks">Tap blocks in order.</div><div class="builderBlocks">${blocks.map((b,i)=>`<button type="button" class="block js-block" data-block-index="${i}">${escapeHTML(b)}</button>`).join('')}</div><button type="button" class="btn primary" id="builderCheck">Check</button><div id="gameFeedback"></div>`}
function renderPatternGame(g){return renderBuilderGame({prompt:g.prompt,answer:g.answer,blocks:g.answer.replace(/[;,.?]/g,'').split(' ')})}
function pickBlock(btn,b){buildSelected.push(b);btn.disabled=true;btn.style.opacity=.45;document.getElementById('answerBlocks').textContent=buildSelected.join(' ')}
function normalize(s){return String(s).toLowerCase().replace(/[;,.?]/g,'').replace(/\s+/g,' ').trim()}
function escapeHTML(x){return String(x).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]})}
function checkBuilder(answer){let ok=normalize(buildSelected.join(' '))===normalize(answer);document.getElementById('gameFeedback').innerHTML=`<div class="notice ${ok?'':'warn'}">${ok?'Correct +10 XP':'Correct answer: '+escapeHTML(answer)}</div><button type="button" class="btn primary" id="nextGameBtn">Next</button>`;document.getElementById('nextGameBtn').addEventListener('click',()=>nextGame(ok));}
function attachGameHandlers(){document.querySelectorAll('#gameArea .js-choice').forEach(btn=>btn.addEventListener('click',()=>answerMC(btn,currentMCOptions[+btn.dataset.choiceIndex],currentMCAnswer)));document.querySelectorAll('#gameArea .js-block').forEach(btn=>btn.addEventListener('click',()=>pickBlock(btn,currentBuilderBlocks[+btn.dataset.blockIndex])));let check=document.getElementById('builderCheck');if(check)check.addEventListener('click',()=>checkBuilder(currentBuilderAnswer));}
function renderMatchMenu(){matchMenu.style.display='block';matchMenu.innerHTML=MATCH_ROUNDS.map((r,i)=>`<button class="gameType" onclick="startMatch(${i})"><div>${r.title}<small>${r.type} · 5 quick choices</small></div><span>›</span></button>`).join('');matchArea.innerHTML=''}
let matchRound=null,matchIndex=0,matchScore=0;function startMatch(i){matchRound=MATCH_ROUNDS[i];matchIndex=0;matchScore=0;matchMenu.style.display='none';renderMatchBoard();setTimeout(()=>{match.scrollIntoView({behavior:'smooth',block:'start'});},40);}
let currentMatchOptions=[],currentMatchAnswer='';function renderMatchBoard(){let p=matchRound.pairs[matchIndex];if(!p){matchArea.innerHTML=`<div class="gameCard"><button type="button" class="btn inlineTopBtn" onclick="renderMatchMenu();match.scrollIntoView({behavior:'smooth',block:'start'});">← Back to Match rounds</button><div class="notice">Round complete. Score: ${matchScore}/${matchRound.pairs.length}. +${matchScore*5} XP</div></div>`;return}let pool=matchRound.pairs.map(x=>x.greek).filter(x=>x!==p.greek);let opts=shuffle([p.greek,...shuffle(pool).slice(0,3)]);currentMatchOptions=opts;currentMatchAnswer=p.greek;matchArea.innerHTML=`<div class="gameCard"><button type="button" class="btn inlineTopBtn" onclick="renderMatchMenu();match.scrollIntoView({behavior:'smooth',block:'start'});">← Back to Match rounds</button><div class="label">${escapeHTML(matchRound.title)} · ${matchIndex+1}/${matchRound.pairs.length}</div><div class="progressBar"><div class="progressFill" style="width:${Math.round((matchIndex/matchRound.pairs.length)*100)}%"></div></div><div class="matchSimple"><div class="matchPrompt"><div class="label">Match this flashcard</div><div class="english">${escapeHTML(p.english)}</div></div>${opts.map((o,i)=>`<button type="button" class="matchOption js-match-option" data-match-index="${i}">${escapeHTML(o)}</button>`).join('')}</div><div id="matchFeedback"></div></div>`;attachMatchHandlers();}
function answerMatch(btn,choice,answer){let ok=choice===answer;btn.classList.add(ok?'correct':'wrong');[...btn.parentNode.querySelectorAll('.matchOption')].forEach(b=>{b.disabled=true;if(currentMatchOptions[+b.dataset.matchIndex]===answer)b.classList.add('correct')});if(ok){matchScore++;bumpXP(5,true)}else{bumpXP(1,false)}document.getElementById('matchFeedback').innerHTML=`<div class="notice ${ok?'':'warn'}">${ok?'Correct match.':'Correct match: '+escapeHTML(answer)}</div><button type="button" class="btn primary" id="nextMatchBtn">Next</button>`;document.getElementById('nextMatchBtn').addEventListener('click',()=>{matchIndex++;renderMatchBoard();});}
function attachMatchHandlers(){document.querySelectorAll('#matchArea .js-match-option').forEach(btn=>btn.addEventListener('click',()=>answerMatch(btn,currentMatchOptions[+btn.dataset.matchIndex],currentMatchAnswer)));}function openTranslate(){let q=builderEnglish.value.trim();if(!q){alert('Type the English phrase first.');return}window.open('https://translate.google.com/?sl=en&tl=el&text='+encodeURIComponent(q)+'&op=translate','_blank')}
function savePersonalPhrase(){let english=builderEnglish.value.trim(),greek=builderGreek.value.trim(),pron=builderPron.value.trim(),category=builderCat.value;if(!english||!greek){alert('Add English and Greek first.');return}state.personal.unshift({english,greek,pron,category});builderEnglish.value='';builderGreek.value='';builderPron.value='';bumpXP(10,true);save();renderPersonal();}
function renderPersonal(){personalList.innerHTML='<h3>Saved Personal Phrases</h3>'+(state.personal.map((p,i)=>`<div class="item${itemClass('personal_'+i)}"><div class="label">${p.category}</div><div class="itemFront">${p.english} ${badge('personal_'+i)}</div><div class="greek">${p.greek}</div><div class="pron">${p.pron||''}</div><div class="actions"><button class="btn review${activeMark('personal_'+i,'review')}" onclick="mark('personal_${i}','review')">Needs Review</button><button class="btn master${activeMark('personal_'+i,'mastered')}" onclick="mark('personal_${i}','mastered')">Mastered</button><button class="btn" onclick="state.personal.splice(${i},1);save();renderPersonal();">Delete</button></div></div>`).join('')||'<div class="notice">No saved phrases yet.</div>')}
if('serviceWorker' in navigator){navigator.serviceWorker.register('./service-worker.js').catch(()=>{});}setup();
